SELECT json_build_object('table_owner',(SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid='ashlar_profile_custody.original'::regclass),'function',(SELECT json_build_object('owner',pg_get_userbyid(proowner),'security_definer',prosecdef,'parallel',proparallel,'volatility',provolatile,'strict',proisstrict,'config',proconfig,'acl',proacl::text) FROM pg_proc WHERE oid='ashlar_profile_custody.retain(text,text,bytea,bytea)'::regprocedure),'roles',(SELECT json_agg(json_build_object('name',rolname,'login',rolcanlogin,'superuser',rolsuper)) FROM pg_roles WHERE rolname LIKE 'ashlar_profile_custody_%'),'matrix',(SELECT json_agg(json_build_object('role',rolname,'select',has_table_privilege(rolname,'ashlar_profile_custody.original','SELECT'),'insert',has_table_privilege(rolname,'ashlar_profile_custody.original','INSERT'),'update',has_table_privilege(rolname,'ashlar_profile_custody.original','UPDATE'),'delete',has_table_privilege(rolname,'ashlar_profile_custody.original','DELETE'),'execute',has_function_privilege(rolname,'ashlar_profile_custody.retain(text,text,bytea,bytea)','EXECUTE'))) FROM pg_roles WHERE rolname IN ('ashlar_profile_custody_owner','ashlar_profile_custody_writer','ashlar_profile_custody_reader')));
